import sys

def parse_input():
    t = int(sys.stdin.readline().strip())
    test_cases = []
    for _ in range(t):
        k = int(sys.stdin.readline().strip())
        first_row = list(map(int, sys.stdin.readline().strip().split()))
        second_row = list(map(int, sys.stdin.readline().strip().split()))
        test_cases.append((k, first_row, second_row))
    return test_cases

def find_empty(grid):
    for i, row in enumerate(grid):
        if 'E' in row:
            return (i, row.index('E'))

def move_organ(grid, empty, target, move):
    x, y = empty
    if move == 'u':
        grid[x][y], grid[x-1][y] = grid[x-1][y], grid[x][y]
        return (x-1, y)
    elif move == 'd':
        grid[x][y], grid[x+1][y] = grid[x+1][y], grid[x][y]
        return (x+1, y)
    elif move == 'l':
        grid[x][y], grid[x][y-1] = grid[x][y-1], grid[x][y]
        return (x, y-1)
    elif move == 'r':
        grid[x][y], grid[x][y+1] = grid[x][y+1], grid[x][y]
        return (x, y+1)

def is_correct_position(organ, grid, k):
    correct_positions = []
    for i in range(k):
        correct_positions.extend(range(1, 2*k+2))
        correct_positions.extend(range(2*k+2, 4*k+2))
    return grid[0][correct_positions.index(organ)] == organ or grid[1][correct_positions.index(organ)] == organ

def solve_case(k, first_row, second_row):
    grid = [first_row, second_row]
    moves = []
    while not all(is_correct_position(organ, grid, k) for organ in range(1, 4*k+2)):
