        for organ in range(1, 4*k+2):
            if not is_correct_position(organ, grid, k):
                if empty[0] == 0 and empty[1] < 2*k and grid[0][empty[1]+1] == organ:
                    move_organ(grid, empty, organ, 'r')
                    moves.append('r')
                    empty = move_organ(grid, empty, organ, 'r')
                elif empty[0] == 1 and empty[1] < 2*k and grid[1][empty[1]+1] == organ:
                    move_organ(grid, empty, organ, 'r')
                    moves.append('R')
                    empty = move_organ(grid, empty, organ, 'r')
                elif empty[0] == 0 and empty[1] > 0 and grid[0][empty[1]-1] == organ:
                    move_organ(grid, empty, organ, 'l')
                    moves.append('l')
                    empty = move_organ(grid, empty, organ, 'l')
                elif empty[0] == 1 and empty[1] > 0 and grid[1][empty[1]-1] == organ:
                    move_organ(grid, empty, organ, 'L')
                    moves.append('L')
                    empty = move_organ(grid, empty, organ, 'L')
                elif empty[0] == 0 and grid[0][empty[1]] == organ:
                    move_organ(grid, empty, organ, 'u')
                    moves.append('u')
                    empty = move_organ(grid, empty, organ, 'u')
                elif empty[0] == 1 and grid[1][empty[1]] == organ:
                    move_organ(grid, empty, organ, 'U')
                    moves.append('U')
                    empty = move_organ(grid, empty, organ, 'U')
                elif empty[0] == 1 and empty[1] < 2*k and grid[1][empty[1]] == organ:
                    move_organ(grid, empty, organ, 'd')
                    moves.append('d')
                    empty = move_organ(grid, empty, organ, 'd')
                elif empty[0] == 0 and empty[1] < 2*k and grid[0][empty[1]] == organ:
                    move_organ(grid, empty, organ, 'D')
                    moves.append('D')
                    empty = move_organ(grid, empty, organ, 'D')
    return 'SURGERY COMPLETE', moves

def main():
    test_cases = parse_input()
    for k, first_row, second_row in test_cases:
        result, moves = solve_case(k, [first_row, second_row])
        print(result)
        if result == 'SURGERY COMPLETE':
            print(''.join(moves))
            print('DONE')
        else:
            print('DONE')

if __name__ == "__main__":
    main()
